benchmark_pascal_source_template:
const marker:array[1..1]of byte=($C9);
var f:file of integer;i,v:integer;
procedure stamp;external $80B7;
begin
  if addr(marker)<>$80B7 then halt;
  Assign(f,'%DRIVE%:/BENCHIO.DAT');Rewrite(f);
  stamp;
  for i:=1 to 128 do begin v:=i;Write(f,v)end;
  Close(f);Reset(f);
  for i:=1 to 128 do begin Read(f,v);if v<>i then halt end;
  Close(f);stamp;
end.
